const ALPH = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
// Python str.rstrip() whitespace set (str.isspace()==True), BMP-ish common set
const PY_WS = new Set([0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,
 0x1680,0x2000,0x2001,0x2002,0x2003,0x2004,0x2005,0x2006,0x2007,0x2008,0x2009,0x200a,
 0x2028,0x2029,0x202f,0x205f,0x3000]);
function pyRstrip(s){
  const cps=[...s];
  let n=cps.length;
  while(n>0 && PY_WS.has(cps[n-1].codePointAt(0))) n--;
  return cps.slice(0,n).join('');
}
function pyRepr(bytes){
  // python bytes repr
  let hasS = bytes.includes(0x27), hasD = bytes.includes(0x22);
  let q = (hasS && !hasD) ? '"' : "'";
  let out = "b" + q;
  for(const b of bytes){
    if(b===0x5c) out+='\\\\';
    else if(b===q.charCodeAt(0)) out+='\\'+q;
    else if(b===0x09) out+='\\t';
    else if(b===0x0a) out+='\\n';
    else if(b===0x0d) out+='\\r';
    else if(b>=0x20 && b<0x7f) out+=String.fromCharCode(b);
    else out+='\\x'+b.toString(16).padStart(2,'0');
  }
  return out+q;
}
function b58decode(v){
  v = pyRstrip(v);
  // ascii encode
  const cps=[...v];
  for(let i=0;i<cps.length;i++){
    const cp=cps[i].codePointAt(0);
    if(cp>127){
      const e=new Error('enc'); e.kind='UnicodeEncodeError'; e.cp=cp; e.pos=i; throw e;
    }
  }
  const origlen=v.length;
  let s=v; let i=0; while(i<s.length && s[i]==='1') i++;
  s=s.slice(i);
  const newlen=s.length;
  let acc=0n;
  for(const ch of s){
    const idx=ALPH.indexOf(ch);
    if(idx<0){ const e=new Error('val'); e.kind='ValueError'; e.ch=ch; throw e; }
    acc=acc*58n+BigInt(idx);
  }
  const res=[];
  while(acc>0n){ res.push(Number(acc%256n)); acc=acc/256n; }
  const arr=res.concat(new Array(origlen-newlen).fill(0)).reverse();
  return Buffer.from(arr);
}
module.exports={b58decode,pyRepr,pyRstrip,ALPH};
if(require.main===module){
  const v=process.argv[2];
  try{ console.log(pyRepr(b58decode(v))); }
  catch(e){ console.log('ERR:'+e.kind+':'+(e.kind==='ValueError'?e.ch:e.cp+'@'+e.pos)); }
}
